def subtract(a, b):
    def normalize(intervals):
        # Remove empty intervals and sort by start position
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()

        # Merge overlapping and touching intervals
        merged = []
        for start, end in valid:
            if merged and start <= merged[-1][1]:
                # Overlapping or touching: merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping: add new interval
                merged.append([start, end])

        return merged

    # Normalize both input lists
    a_norm = normalize(a)
    b_norm = normalize(b)

    if not a_norm:
        return []

    # For each interval in a, subtract all intervals in b
    result = []

    for a_start, a_end in a_norm:
        # Start with the full interval from a
        current_intervals = [[a_start, a_end]]

        # Subtract each interval in b
        for b_start, b_end in b_norm:
            next_intervals = []
            for c_start, c_end in current_intervals:
                # Check if b interval overlaps with current interval
                if b_end <= c_start or b_start >= c_end:
                    # No overlap, keep the interval
                    next_intervals.append([c_start, c_end])
                else:
                    # There is overlap, split the interval
                    if c_start < b_start:
                        next_intervals.append([c_start, b_start])
                    if c_end > b_end:
                        next_intervals.append([b_end, c_end])
            current_intervals = next_intervals

        result.extend(current_intervals)

    # Merge touching/overlapping intervals in result
    if not result:
        return []

    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

